# IRT conventions measured on the local bank (active tasks, 2026-10-06; SELECT only).
# multiple_choice: irt_guessing mode = median = 0.2000 (590 of 854 active MC rows;
#   263 rows carry the unconverted 0.0 default, 1 row 0.25).
# difficulty B, grades 9/10/11 (ids G9_/G10_/G11_): irt_difficulty mode = median = 0.5000
#   (G9 1755 tasks, G10 1688, G11 2503; the same by skill class level 9/10/11).
# Tasks converted to multiple_choice therefore get c=0.2 (3PL guessing floor of a
# 4-option item); tasks that were difficulty C only because they asked for a full
# proof or derivation, and now ask for recognition of one defined fact, drop to B.
MC_GUESSING = 0.2
B_IRT_DIFFICULTY = 0.5
C_TO_B = ('G11_TB_10_5*_10_23*', 'G11_TB_§26_11_1', 'G11_TB_§26_11_2', 'G9_TB_ЗПТ_888')

DEFERRED_BATCH = 'n01-source-repair-2026-10-06-w6b'
HISTORICAL = ('G11_TB_§9_3_6', 'ds_llm_7c36694c8cba')


def with_irt(source, repairs):
    rows = {row['id']: row for row in source['content']['tasks']}
    result = copy.deepcopy(repairs)
    for task_id, spec in result.items():
        row, changes = rows[task_id], spec['changes']
        if changes.get('answer_type') == 'multiple_choice' and float(row.get('irt_guessing') or 0) != MC_GUESSING:
            changes['irt_guessing'] = MC_GUESSING
        if task_id in C_TO_B:
            if row['difficulty'] != 'C':
                raise ValueError(f'{task_id}: expected difficulty C before lowering')
            changes['difficulty'] = 'B'
            changes['irt_difficulty'] = B_IRT_DIFFICULTY
    return result


def final_manifest(source):
    from tools.content_review.n01_review_knowledge import NODES
    manifest = build(source, with_irt(source, REPAIRS), BATCH)
    manifest['knowledge_nodes'] = NODES
    manifest['historical_protection_required'] = []
    manifest['navigation_note'] = 'New nodes are inactive pending N02 measurement/graph acceptance; no new active CAT sections.'
    return manifest


def deferred_manifest(source):
    """Tasks whose historical answers need snapshot-safe acceptance: apply only
    with the explicit --ack-protected flag after the owner has decided."""
    manifest = build(source, with_irt(source, DEFERRED_REPAIRS), DEFERRED_BATCH)
    manifest['knowledge_nodes'] = []
    manifest['historical_protection_required'] = list(HISTORICAL)
    manifest['navigation_note'] = 'Deferred from w6: historical pupil answers exist; no taxonomy changes.'
    return manifest


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', required=True, type=Path)
    parser.add_argument('--output', required=True, type=Path)
    parser.add_argument('--output-deferred', required=True, type=Path)
    args = parser.parse_args()
    source = json.loads(args.source.read_text())
    for path, make in ((args.output, final_manifest), (args.output_deferred, deferred_manifest)):
        path.write_text(json.dumps(make(source), ensure_ascii=False, indent=2)+'\n')
